use vstd::prelude::*;

verus! {

/// Element-wise bitwise OR of two equal-length byte arrays.
fn bitwise_or(a: Vec<u8>, b: Vec<u8>) -> (result: Vec<u8>)
    requires
        a.len() == b.len(),
    ensures
        // output has same length
        result.len() == a.len(),

        // element-wise OR, order preserved
        forall|i: int|
            0 <= i < a.len() ==>
                result[i] == (a[i] | b[i]),

        // (optional) result bytes are in range (automatic for u8, but stated explicitly)
        forall|i: int|
            0 <= i < result.len() ==>
                0 <= result[i] <= 255,
{
    let n = a.len();
    let mut result: Vec<u8> = Vec::new();

    let mut i: usize = 0;
    while i < n
        invariant
            n == a.len(),
            n == b.len(),
            result.len() == i,
            i <= n,
            forall|j: int|
                0 <= j < i as int ==> result[j] == (a[j] | b[j]),
    {
        let x = a[i];
        let y = b[i];
        result.push(x | y);
        i += 1;
    }

    result
}

} // verus!